          {/* My Added Beers */}
          {userBeers.length > 0 && (
            <div className="bg-white rounded-xl shadow-xl p-8 mt-8 border-4 border-gray-200">
              <h3 className="text-2xl font-bold text-gray-900 mb-6 font-serif select-none">🍺 Beers I've Added</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {userBeers.map((beer) => (
                  <BeerCard key={beer._id} beer={beer} onClick={handleBeerSelect} />
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    );
  };

  const renderPage = () => {
    switch(currentPage) {
      case 'home':
        return <HomePage />;
      case 'beers':
        return <BeersPage />;
      case 'friends':
        return <FriendsPage />;
      case 'add':
        return <AddBeerPage />;
      case 'login':
        return <LoginPage />;
      case 'register':
        return <RegisterPage />;
      case 'beer-detail':
        return <BeerDetailPage />;
      case 'user-profile':
        return <UserProfilePage />;
      case 'profile':
        return <ProfilePage />;
      default:
        return <HomePage />;
    }
  };
  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-white">
      <Navigation />
      {renderPage()}
    </div>
  );
};

export default BeerReviewApp;
